<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$slug=defined('LEARNING_LANGUAGE')?LEARNING_LANGUAGE:'html';$c=learning_course($slug);$uid=learning_user_id();$st=learning_course_stats((int)$c['id'],$uid);$eligible=$st['total']>0&&$st['done']===$st['total'];$pdo=learning_pdo();$cert=null;if($eligible){$q=$pdo->prepare("SELECT * FROM learning_certificates WHERE user_id=? AND course_id=?");$q->execute([$uid,$c['id']]);$cert=$q->fetch();if(!$cert){$no='STZ-'.date('Y').'-'.strtoupper(bin2hex(random_bytes(5)));$hash=hash('sha256',$uid.'|'.$c['id'].'|'.$no);$i=$pdo->prepare("INSERT INTO learning_certificates(user_id,course_id,certificate_no,verification_hash) VALUES(?,?,?,?)");$i->execute([$uid,$c['id'],$no,$hash]);$q->execute([$uid,$c['id']]);$cert=$q->fetch();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Certificate</title><style>body{margin:0;background:#080a10;color:#fff;font-family:Inter,system-ui}.wrap{max-width:900px;margin:auto;padding:35px 18px}.cert{padding:55px 30px;text-align:center;border:1px solid #fff2;border-radius:20px;background:linear-gradient(135deg,#111827,#0c111a);box-shadow:0 30px 90px #0008}.small{color:#8993a5;font-size:9px}.eyebrow{font-size:9px;letter-spacing:2px;color:#a78bfa;font-weight:900}.name{font-size:30px;margin:16px}.id{margin-top:12px;font-size:10px}</style></head><body><div class=wrap><a href=index.php style="color:#a78bfa;font-size:8px">← Course</a><div class=cert><?php if($cert):?><div class=eyebrow>CERTIFICATE OF COMPLETION</div><h1><?=eh($c['title'])?></h1><div class=name><?=eh((string)($_SESSION['user_name']??'Learner'))?></div><div class=small>has successfully completed this course</div><div class=id>Certificate ID: <?=eh($cert['certificate_no'])?></div><div class=small>Issued: <?=eh($cert['issued_at'])?></div><?php else:?><div class=eyebrow>CERTIFICATE LOCKED</div><h1><?=eh($c['title'])?></h1><p class=small>Complete all lessons to unlock your certificate.</p><p class=small>Current progress: <?=$st['percent']?>%</p><?php endif;?></div></div></body></html>